  int remaining = decimal;
  while (remaining > 0) {
    binaryDigits.add(remaining % 2 == 1 ? '1' : '0'); 
    remaining ~/= 2; 
  }


  String result = '';
  for (int i = binaryDigits.length - 1; i >= 0; --i) {
    result += binaryDigits[i];
  }
  return "db$result$db";
}

