class Deque<T> {
  final List<T> _data = [];

  bool get isEmpty => _data.isEmpty;
  T? front() => !isEmpty ? _data[0] : null;
  void add(T value) => _data.add(value);
  void removeFirst() {
    if (!_data.isEmpty) _data.removeAt(0);
  }
  T? last() => _data.isNotEmpty ? _data[_data.length - 1] : null;
  void removeLast() {
    if (_data.isNotEmpty) _data.removeLast();
  }
}

