  var largest = lst.where((x) => x > 0).toList();

  var maxNegative = smallest.isNotEmpty ? smallest.reduce((a, b) => a > b ? a : b) : null;
  var minPositive = largest.isNotEmpty ? largest.reduce((a, b) => a < b ? a : b) : null;

  return [maxNegative, minPositive];
}

